import React from 'react';

const ResumePage = () => {
  return (
    <div className="resume-page" style={styles.resumePage}>
      <header>
        <nav>
          <ul style={styles.navList}>
            <li style={styles.navItem}><a href="/" style={styles.navLink}>Projects</a></li>
            <li style={styles.navItem}><a href="/resume" style={styles.navLink}>Resume</a></li>
          </ul>
        </nav>
      </header>
      <div className="resume-content" style={styles.resumeContent}>
        <h1>Resume</h1>
        {/* Add your resume content here */}
      </div>
      <div style={styles.fancyNotation}>
        <p style={styles.notationText}>Website in the making 🚧</p>
      </div>
    </div>
  );
};

const styles = {
  resumePage: {
    backgroundColor: '#fff',
    color: '#000',
    textAlign: 'center',
    minHeight: '100vh',
    position: 'relative', // Make sure the notation is positioned relative to this container
  },
  navList: {
    listStyle: 'none',
    display: 'flex',
    justifyContent: 'flex-end',
    padding: '20px',
    margin: 0
  },
  navItem: {
    margin: '0 10px'
  },
  navLink: {
    color: '#000',
    textDecoration: 'none'
  },
  resumeContent: {
    marginTop: '20px'
  },
  fancyNotation: {
    position: 'absolute',
    bottom: '20px',
    left: '50%',
    transform: 'translateX(-50%)',
    backgroundColor: '#ffcc00',
    padding: '10px 20px',
    borderRadius: '30px',
    boxShadow: '0px 4px 8px rgba(0, 0, 0, 0.1)',
    zIndex: '1000', // Ensures it's above other content
    animation: 'pulse 1.5s infinite',
  },
  notationText: {
    margin: 0,
    color: '#000',
    fontWeight: 'bold',
    fontSize: '16px',
  },
  '@keyframes pulse': {
    '0%': { transform: 'scale(1)' },
    '50%': { transform: 'scale(1.05)' },
    '100%': { transform: 'scale(1)' },
  },
};

export default ResumePage;
